Listing 4.3 Implementing a rubric to judge an AI agent from langchain.prompts import ChatPromptTemplate from pydantic import BaseModel, Field # Define the Pydantic model for structured output (using chain of thought) class ScoreResponse(BaseModel): reasoning: str = Field(description="The reasoning process of what score you should pick") score: int = Field(description="An integer between 0 and 3 representing the correctness of the AI response compared to the ground truth") # Create a prompt template for scoring AI responses against ground truth score_prompt = ChatPromptTemplate.from_messages([ ( "system", ( "You are an expert evaluator. " "Given an AI's response to a question and the ground truth answer, " "score the AI's response on a scale from 0 to 3 based on correctness:
" "0 = Completely incorrect or irrelevant
" "1 = Partially correct, but with major errors or omissions
" "2 = Mostly correct, but with minor errors or missing details
" "3 = Completely correct and matches the ground truth" ) ), ( "human", ( "Question: {question}
" "AI Response: {ai_response}
" "Ground Truth: {ground_truth}

" "Score the AI response from 0 to 3." ) )
